<?php
declare(strict_types=1);namespace App\Service;use App\Exception\AuthException;use Hyperf\Contract\IdGeneratorInterface;use Hyperf\Database\ConnectionInterface;use Hyperf\DbConnection\Db;
/** 维护供应商 HTTPS 上游路由并解析已发布端点的转发目标。 */
final class GatewayRouteService{public function __construct(private Db$db,private IdGeneratorInterface$ids){}public function save(int$supplierId,int$endpointId,string$url):void{$url=trim($url);$parts=parse_url($url);if(!is_array($parts)||($parts['scheme']??'')!=='https'||!isset($parts['host'])||isset($parts['user'])||isset($parts['pass'])||strlen($url)>2048)throw AuthException::badRequest('上游地址必须是无凭据 HTTPS URL。');$this->db->transaction(function(ConnectionInterface$c)use($supplierId,$endpointId,$url):void{if($c->selectOne('SELECT e.`id` FROM `api_endpoints` e INNER JOIN `api_versions` v ON v.`id`=e.`api_version_id` INNER JOIN `api_products` p ON p.`id`=v.`api_product_id` WHERE e.`id`=? AND p.`supplier_profile_id`=? AND e.`deleted_at` IS NULL LIMIT 1 FOR UPDATE',[$endpointId,$supplierId])===null)throw AuthException::badRequest('端点不存在。');$c->insert('INSERT INTO `gateway_routes` (`id`,`api_endpoint_id`,`supplier_profile_id`,`upstream_url`,`status`,`config_version`,`created_at`,`updated_at`,`deleted_at`) VALUES (?,?,?, ?,\'active\',1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,NULL) ON DUPLICATE KEY UPDATE `upstream_url`=VALUES(`upstream_url`),`status`=\'active\',`config_version`=`config_version`+1,`updated_at`=CURRENT_TIMESTAMP,`deleted_at`=NULL',[$this->ids->generate(),$endpointId,$supplierId,$url]);});}/** @return ?array<string,mixed> */public function resolve(int$versionId,string$method,string$path):?array{$r=$this->db->selectOne('SELECT r.`upstream_url`,e.`id` AS `endpoint_id` FROM `gateway_routes` r INNER JOIN `api_endpoints` e ON e.`id`=r.`api_endpoint_id` WHERE e.`api_version_id`=? AND e.`method`=? AND e.`path`=? AND r.`status`=\'active\' AND r.`deleted_at` IS NULL AND e.`deleted_at` IS NULL LIMIT 1',[$versionId,strtoupper($method),$path]);return$r===null?null:(is_object($r)?get_object_vars($r):$r);}}
